import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"15、【謙】 艮下坤上","description":"周易口訣義 - 15、【謙】 艮下坤上","frontmatter":{"title":"15、【謙】 艮下坤上","description":"周易口訣義 - 15、【謙】 艮下坤上"},"headers":[],"relativePath":"classics/koujueyi/017.md","filePath":"classics/koujueyi/017.md"}'),r={name:"classics/koujueyi/017.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_15、【謙】-艮下坤上" tabindex="-1">15、【謙】 艮下坤上 <a class="header-anchor" href="#_15、【謙】-艮下坤上" aria-label="Permalink to “15、【謙】 艮下坤上”">​</a></h1><p>彖曰：「謙亨」。天道下濟而光明，地道卑而上行。天道虧盈而益謙，地道變盈而流謙，鬼神害盈而福謙，人道惡盈而好謙。謙尊而光，卑而不可逾，君子之終也。</p><p>象曰：地中有山，謙。君子以裒多益寡，稱物平施。</p><p>初六：謙謙君子，用涉大川，吉。</p><p>象曰：「謙謙君子」，卑以自牧也。</p><p>六二：鳴謙，貞吉。</p><p>象曰：「鳴謙貞吉」，中心得也。</p><p>九三：勞謙，君子有終，吉。</p><p>象曰：「勞謙君子」，萬民服也。</p><p>六四：無不利，撝謙。</p><p>象曰：「無不利，撝謙」，不違則也。</p><p>六五，不富以其鄰，利用侵伐，無不利。</p><p>象曰：「利用侵伐」，徵不服也。</p><p>上六，鳴謙，利用行師，徵邑國。</p><p>象曰：「鳴謙」，志未得也。可用行師，徵邑國也。</p><p>解讀</p><p>謙亨者，謙是屈己先人，以自卑巽為用，如是何往而不亨也！「君子有終」者，小人行謙，多不能久，惟有君子盡能保終也。象曰「地中有山，謙」者，九家易義曰：山至高，地至卑，以高下卑，故云謙也。所以言地中者，以明多之與少，俱行其謙也。「君子以裒多益寡，稱物平施」者，裒，聚也；寡，少也；謂人資財此多者行謙，即物益裒聚，故曰「裒多」也；比寡少行謙，即物漸增益，故曰「益寡」也；稱量事物，隨其多少，均平而施給，故曰「稱物平施」也。</p><p>「初六，謙謙君子，用涉大川，吉」者，處謙更在下，則是卑退之甚也，故曰「謙謙」也；君子以謙自牧，守謙不失，用濟大難，物無見害，故曰「用涉大川，吉」。牧，養也。</p><p>「六二鳴謙，貞吉」者，鳴者，聲名聞之謂也。處謙之時，位居中正，即謙之聲聞於外境，是正而獲吉，故曰「鳴謙，貞吉」。</p><p>「九三：勞謙，君子有終，吉」者，九三以剛陽之質，為一卦之主，上即承奉於君，下又撫綏萬人，勞勤于謙，以君子處之，能保其終而獲吉。</p><p>「六四：無不利，撝謙」者，六四上近至尊，下近權臣，處是時，不可違于謙巽，故三之於五，有事指撝，無不從順，不敢違於法則，故曰「無不利，撝謙」也。</p><p>六五：不富以其鄰，利用侵伐，無不利者，六五為謙之君，教化大行，下既行「謙」，人自富貴，故不假以財物，賙贍於鄰，故曰「不富以其鄰」。身既謙卑，不妄加討伐，若有驕逆不行此道者，故用誅伐，故云「利用侵伐，無不利」。張氏雲「葛伯仇餉，湯往伐之」是也。</p><p>上六：鳴謙，利用行師，徵邑國者，不預內政，于謙不實，惟有虛聲外揚而已，故曰「鳴謙」也。有所興為，其功未得，但可徵旁邑國驕逆之人，故曰「利用行師徵邑國」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
